export const SCOPE = "atproto blob:image/* include:site.standard.authFull";
export const AUTH_CALLBACK_PATH = "/auth/callback/";

const HANDLE_RESOLVER = "https://bsky.social";

export interface AtprotoSession {
  did: string;
